/*
 * A362910  Semiprimes p*q for which p <= q < p^3.
 * https://oeis.org/A362910
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 none, u16 none, u32 n <= 57, u64 n <= 57, u128 n <= 57,
 *            big any n
 * Helpers:   build_primes_upto
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by enumerating all semiprimes p*q with p ≤ q < p³
   and collecting them in ascending order. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/build_primes_upto.h"

typedef struct {
    seq_t val;      /* p * q */
    size_t pi;      /* index of the smaller prime p */
    size_t qi;      /* index of the larger prime q */
} node_t;

/* ======== Static state ============================================ */
static bool initialized = false;
static idx_t prime_limit = 0;          /* current maximal prime limit   */
static uint64_t *prime_buf = NULL;     /* array of primes              */
static size_t prime_cnt = 0;           /* number of primes retrieved   */

static size_t heap_cap = 0;
static size_t heap_size = 0;
static node_t *heap = NULL;

static size_t a_cap = 0;
static size_t a_len = 0;
static seq_t *a_vals = NULL;

/* ======== Helper: grow heap ======================================== */
static void heap_grow(void)
{
    size_t new_cap = (heap_cap == 0) ? 16 : heap_cap * 2;
    heap = (node_t *)realloc(heap, new_cap * sizeof(node_t));
    heap_cap = new_cap;
}

/* ======== Heap operations ========================================== */
static void heapify_down(size_t i)
{
    while (true) {
        size_t l = 2 * i + 1;
        size_t r = l + 1;
        size_t smallest = i;
        if (l < heap_size && heap[l].val < heap[smallest].val) smallest = l;
        if (r < heap_size && heap[r].val < heap[smallest].val) smallest = r;
        if (smallest != i) {
            node_t tmp = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = tmp;
            i = smallest;
        } else break;
    }
}

static void heapify_up(size_t i)
{
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[i].val < heap[parent].val) {
            node_t tmp = heap[i];
            heap[i] = heap[parent];
            heap[parent] = tmp;
            i = parent;
        } else break;
    }
}

static void heap_push(node_t node)
{
    if (heap_size == heap_cap) heap_grow();
    heap[heap_size++] = node;
    heapify_up(heap_size - 1);
}

static node_t heap_pop(void)
{
    node_t top = heap[0];
    heap[0] = heap[--heap_size];
    if (heap_size > 0) heapify_down(0);
    return top;
}

/* ======== Helper: grow array of a_vals ============================ */
static void a_grow(void)
{
    size_t new_cap = (a_cap == 0) ? 256 : a_cap * 2;
    a_vals = (seq_t *)realloc(a_vals, new_cap * sizeof(seq_t));
    a_cap = new_cap;
}

/* ======== Initialization ========================================= */
static void init(void)
{
    if (initialized) return;
    initialized = true;

    /* Choose a prime limit that guarantees we find the first
       few thousands of semiprimes.  2 000 000 primes generate
       more than enough products for n up to ~10 000.           */
    prime_limit = 2000000;
    build_primes_upto(prime_limit, &prime_buf, &prime_cnt);

    heap_cap = (heap_size = 0);
    heap = (node_t *)malloc(heap_cap * sizeof(node_t));

    /* Push initial nodes p * p for every prime p */
    for (size_t i = 0; i < prime_cnt; ++i) {
        node_t n = { (seq_t)prime_buf[i] * (seq_t)prime_buf[i], i, i };
        heap_push(n);
    }

    a_cap = 256;
    a_vals = (seq_t *)malloc(a_cap * sizeof(seq_t));
    a_len = 0;
}

/* ======== The required function ==================================== */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* the sequence starts at index 1 */
    init();                 /* ensure resources are ready */

    /* Generate terms until we have at least n of them. */
    while (a_len < n) {
        node_t cur = heap_pop();
        if (a_len == a_cap) a_grow();
        a_vals[a_len++] = cur.val;

        size_t i = cur.pi;
        size_t j = cur.qi + 1;
        if (j < prime_cnt) {
            uint64_t p = prime_buf[i];
            uint64_t p3 = p * p * p;        /* p³ fits in 64‑bit for this limit */

            if (prime_buf[j] < p3) {
                node_t nxt = { (seq_t)p * (seq_t)prime_buf[j], i, j };
                heap_push(nxt);
            }
        }
    }

    return a_vals[n - 1];
}
